def comp_palette(g,minsize=6):
 h,w=len(g),len(g[0]); seen=set(); sizes=Counter()
 for i in range(h):
  for j in range(w):
   if (i,j) in seen: continue
   col=g[i][j]; stack=[(i,j)]; seen.add((i,j)); n=0
   while stack:
    y,x=stack.pop(); n+=1
    for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
     if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and g[yy][xx]==col:
      seen.add((yy,xx)); stack.append((yy,xx))
   sizes[col]=max(sizes[col],n)
 return {c for c,n in sizes.items() if n>=minsize},sizes
