def weighted(g,pal,rad=4,power=2):
 h,w=len(g),len(g[0]);out=[r[:] for r in g]
 for i in range(h):
  for j in range(w):
   if g[i][j] in pal:continue
   score=Counter()
   for y in range(max(0,i-rad),min(h,i+rad+1)):
    for x in range(max(0,j-rad),min(w,j+rad+1)):
     if g[y][x] in pal and (y,x)!=(i,j):
      d=abs(y-i)+abs(x-j); score[g[y][x]]+=1/(d**power)
   if score: out[i][j]=score.most_common(1)[0][0]
 return out
